function AboutMe() {
  return (
    <header className="about-me-header">
      <h2 className="name-title">Radin Hemmasi</h2>
      <h1 className="title">
        I make complex things simple, and do simple things Well
      </h1>
      <p className="text">
        I’m Radin Hemmasi, a full-stack developer and student passionate about
        technology and building useful software. With six years of experience in
        Python, I enjoy solving problems and turning ideas into practical
        applications. I work across frontend, backend, and mobile development,
        and I’m always exploring new technologies and improving my skills.
      </p>
    </header>
  );
}

export default AboutMe;
